    cells: { A1: "Monthly spending", B1: "24000", A2: "Savings now", B2: "30000", A3: "Months wanted", B3: "6", A4: "Months covered now", A5: "Target fund", A6: "Still needed", A7: "Months to reach target at 3,000 a month" }, view: { cols: 3, rows: 9 },
