    cells: { A1: "Amount", B1: "10000", A2: "Yearly rate", B2: "8%", A5: "Year", B5: "Compound", C5: "Simple", A6: "0", A7: "1", A8: "2", A9: "3", A10: "4", A12: "Extra from compounding" }, view: { cols: 4, rows: 13 },
